package com.exito.chop;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;
final class ExportKit {
 static final String[] TARGETS={"WAV separados","MPC Live II · XPM + WAV (experimental)","SP-404MKII · WAV para importar","Cubase · WAV + SFZ + MIDI","Serato Studio · WAV para importar","S900 · discos DD nativos","SP-1200 · MIDI SDS + WAV","ISLA S2400 · WAV para importar"};
 static String xpm(String[] files,int[] frames,boolean gate){StringBuilder x=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<MPCVObject><Version><File_Version>2.1</File_Version><Application>MPC-V</Application><Application_Version>2.10.0</Application_Version><Platform>Linux</Platform></Version><Program type=\"Drum\"><ProgramName>ChopGOS</ProgramName><ProgramPolyphony>16</ProgramPolyphony><Instruments>");for(int i=0;i<128;i++){x.append("<Instrument number=\"").append(i+1).append("\"><Volume>1.000000</Volume><Pan>0.500000</Pan><MuteGroup>0</MuteGroup><Polyphony>16</Polyphony><LowNote>0</LowNote><HighNote>127</HighNote><TriggerMode>").append(gate?1:0).append("</TriggerMode><KeyTrack>False</KeyTrack><FilterType>0</FilterType><Cutoff>1.000000</Cutoff><Resonance>0.000000</Resonance><AmpAttack>0.000000</AmpAttack><AmpDecay>1.000000</AmpDecay><AmpSustain>1.000000</AmpSustain><AmpRelease>0.010000</AmpRelease><Layers>");if(i<files.length){String f=files[i];x.append("<Layer number=\"1\"><Active>True</Active><Volume>1.000000</Volume><Pan>0.500000</Pan><Pitch>0.000000</Pitch><SampleName>").append(f.substring(0,f.length()-4)).append("</SampleName><SampleFile>").append(f).append("</SampleFile><SampleStart>0</SampleStart><SampleEnd>").append(frames[i]).append("</SampleEnd><LoopStart>0</LoopStart><LoopEnd>0</LoopEnd><RootNote>61</RootNote><KeyTrack>False</KeyTrack><VelStart>0</VelStart><VelEnd>127</VelEnd></Layer>");}x.append("</Layers></Instrument>");}x.append("</Instruments><PadNoteMap>");for(int i=0;i<128;i++)x.append("<PadNote number=\"").append(i+1).append("\"><Note>").append(i<64?36+i:i<100?i-64:i).append("</Note></PadNote>");return x.append("</PadNoteMap></Program></MPCVObject>").toString();}
 static void wav(ZipOutputStream z,String name,short[] pcm,int rate,int channels)throws IOException{z.putNextEntry(new ZipEntry(name));AudioFiles.writeWav(z,pcm,rate,channels);z.closeEntry();}
 static void export(Engine e,int target,boolean wet){if(!e.ready())return;if(e.padCount()==0){e.message("Marca primero al menos un pad.");return;}e.finishPadMarking(false);e.freezeForEdit();e.harmony.stop();e.sequencer.stop();e.drums.stop();e.stop();final short[] data=e.rendered;final int rate=e.rate,count=e.padCount(),bpm=e.slots.masterBpm;final PadParams[] pads=new PadParams[count];final int[] start=new int[count],end=new int[count];double scale=data.length/(double)e.source.length;for(int i=0;i<count;i++){pads[i]=e.padParams[i].copy();start[i]=(int)(e.start(i)*scale);end[i]=(int)(e.end(i)*scale);}final Mutator.Settings fx=e.mutate.copy();fx.bpm=bpm;final Heat.Settings heat=e.copyHeat();final float comp=e.compression,verb=e.reverb;final boolean gate=e.gate;e.busy=true;e.worker.execute(()->{try{File dir=new File(e.context.getCacheDir(),"exports");dir.mkdirs();File file=new File(dir,"ChopGO_"+new String[]{"WAV","MPC_Live_II","SP404MKII","Cubase","Serato_Studio","S900","SP1200","S2400"}[target]+".zip");String[] names=new String[count];int[] lengths=new int[count];StringBuilder map=new StringBuilder("pad\tbank\tnote_midi\tstart_s\tend_s\tfile\n"),sfz=new StringBuilder("// ChopGOS\n<group> ampeg_attack=0.003 ampeg_release=0.01\n");LegacyDisk.Disk disk=new LegacyDisk.Disk();int disks=1,sds=0;
 try(ZipOutputStream z=new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(file)))){for(int i=0;i<count;i++){short[] rendered=AudioRender.chop(data,rate,start[i],end[i],pads[i],comp,verb,fx,heat,wet);int outRate=target==2||target==7?48000:target==1||target==3||target==4?44100:target==5?40000:target==6?26040:rate;boolean mono=target==5||target==6;short[] audio=outRate==rate&&!mono?rendered:Resampler.convert(rendered,rate,outRate,mono);if(target==2&&audio.length<9600)audio=Arrays.copyOf(audio,9600);String name=String.format(Locale.US,"Chop_%02d.wav",i+1),prefix=target==1?"MPC/":target==2?"IMPORT/":target==7?"S2400/Bank_"+(char)('A'+i/8)+"/":"Samples/";names[i]=name;lengths[i]=audio.length/(mono?1:2);wav(z,prefix+name,audio,outRate,mono?1:2);map.append(i+1).append('\t').append((char)('A'+i/(target==7?8:16))).append('\t').append(36+i).append('\t').append(start[i]/(double)rate).append('\t').append(end[i]/(double)rate).append('\t').append(prefix+name).append('\n');sfz.append("<region> sample=Samples/").append(name).append(" key=").append(36+i).append(" pitch_keycenter=").append(36+i).append(" loop_mode=").append(gate?"no_loop":"one_shot").append('\n');
 if(target==5){for(int at=0,part=0;at<audio.length;at+=460000,part++){short[] fragment=Arrays.copyOfRange(audio,at,Math.min(audio.length,at+460000));String sn=String.format(Locale.US,"C%02dP%02d",i+1,part+1);byte[] packed=LegacyDisk.sample(fragment,outRate,sn);double duration=fragment.length/(double)outRate;if(!disk.fits(packed,duration)){MidiTranscriber.put(z,String.format(Locale.US,"S900/Disk_%02d.img",disks++),disk.bytes);disk=new LegacyDisk.Disk();}disk.add(packed,sn,duration);}}
 if(target==6){int max=65100;for(int at=0,part=0;at<audio.length;at+=max,part++){short[] fragment=Arrays.copyOfRange(audio,at,Math.min(audio.length,at+max));MidiTranscriber.put(z,String.format(Locale.US,"SP1200/Set_%02d/Chop_%02d_Part_%02d.syx",sds/4+1,i+1,part+1),MidiIO.sampleDump(fragment,26040,sds%4));sds++;}}
 e.message("Exportando "+(i+1)+" / "+count+" chops");}
 if(target==1)MidiTranscriber.put(z,"MPC/ChopGO_CHOPS.xpm",xpm(names,lengths,gate).getBytes(StandardCharsets.UTF_8));if(target==3)MidiTranscriber.put(z,"ChopGO_CHOPS.sfz",sfz.toString().getBytes(StandardCharsets.UTF_8));if(target==5&&disk.files>0)MidiTranscriber.put(z,String.format(Locale.US,"S900/Disk_%02d.img",disks),disk.bytes);MidiTranscriber.put(z,"Mapa_chops.tsv",map.toString().getBytes(StandardCharsets.UTF_8));MidiTranscriber.put(z,"Secuenciador_disparos.mid",MidiTranscriber.triggers(e));MidiTranscriber.put(z,"Instrumentos.mid",e.harmony.midi());MidiTranscriber.put(z,"LEEME.txt",readme(target,wet).getBytes(StandardCharsets.UTF_8));}
 e.busy=false;e.main.post(()->MainActivity.launch(e.context,"save-artifact",file.getName()));}catch(Throwable error){e.busy=false;e.message("Exportación: "+Engine.reason(error));}});}
 static String readme(int target,boolean wet){String[] guide={
 "WAV PCM separados con los límites IN/OUT de cada chop. Mapa_chops.tsv contiene las asignaciones.",
 "MPC Live II: conserva ChopGO_CHOPS.xpm junto a los WAV dentro de MPC/. Carga el XPM desde el navegador de MPC. Programa Drum experimental, pendiente de prueba en hardware/software MPC. No es un proyecto XPJ. Bancos A–D; nota 36 = A01, 99 = D16.",
 "SP-404MKII: WAV 48 kHz/16 bits en IMPORT/. Copia los WAV a IMPORT de una SD preparada por la máquina, o impórtalos mediante la app oficial. Asigna los pads según el mapa. Los sonidos menores de 100 ms se rellenan con silencio hasta esa duración. No es un proyecto nativo BIN.",
 "Cubase: arrastra cada WAV a Sampler Control; una pista por chop si quieres instrumentos independientes. SFZ es para samplers compatibles: Sampler Track no importa SFZ. El MIDI de disparos requiere asignar los archivos a sus notas. No contiene CPR ni preset nativo de Sampler Track. La transcripción melódica se exporta desde Audio → MIDI.",
 "Serato Studio: importa los WAV en Samples o arrástralos a un Drum Deck y asigna según el mapa. No es un proyecto .serato-studio ni transfiere automáticamente cues de un Sample Deck.",
 "S900: imágenes DD de 800 KiB con muestras nativas S900, mono/12 bits/40 kHz. Los sonidos largos se dividen sin descartar audio. Cada disco limita las muestras a aproximadamente 11,5 s para respetar la RAM original. Usa una herramienta de escritura de discos Akai, Greaseweazle o un emulador compatible. Copiar el .img como archivo a un disquete DOS no funciona. No incluye programa P ni sistema operativo; asigna los sonidos en la S900. Los WAV de preparación son de 16 bits. Pendiente prueba física.",
 "SP-1200: .syx MIDI Sample Dump Standard, 12 bits/26,04 kHz. Necesitas emisor SDS con handshake e interfaz MIDI. Crea previamente una muestra vacía con su duración en la SP. Se dividen sonidos largos en piezas de hasta 2,5 s; cada Set_XX contiene como máximo cuatro partes, números 0–3, para no exceder los 10 s de una SP original. Carga cada set por separado. No crea disquetes HFE ni bancos/OS nativos. WAV adicionales para conversión/muestreo por audio. SDS debe probarse con tu revisión de firmware y equipo; el archivo por sí solo no realiza el handshake.",
 "ISLA S2400: WAV 48 kHz/16 bits en bancos de ocho. Copia a la SD e importa/asigna. Tiene 32 sample tracks; para 64 chops usa bancos A–D y E–H en dos proyectos. No contiene proyecto nativo ni patrón S2400."};return "ChopGO V03\n\n"+guide[target]+"\n\n"+(wet?"Tono, tempo, color, EQ y FX renderizados en el audio. Colas de hasta 2,5 s. No reapliques el mismo tono/tempo al importar.":"Tono y tempo aplicados; sin color, EQ ni efectos creativos.")+"\nSecuenciador_disparos.mid contiene pads, no notas de la canción. Canales 1–8 = fuentes, notas 36–99 = pads. Instrumentos.mid contiene la progresión interna. No incluye mezcla completa de secuenciador y drums.\n";}
}
